const {
  minutesWaiting,
  waitingPoints,
  complexityPoints,
  promisePoints,
} = require('../../../src/modules/orders/priority');

const NOW = new Date('2026-01-15T12:00:00.000Z');
const MIN = 60 * 1000;
const at = (offsetMs) => new Date(NOW.getTime() + offsetMs);

describe('minutesWaiting', () => {
  test('counts whole minutes only (9m50s -> 9)', () => {
    expect(minutesWaiting({ placed_at: at(-(9 * MIN + 50 * 1000)) }, NOW)).toBe(9);
  });

  test('clamps a future placed_at to zero', () => {
    expect(minutesWaiting({ placed_at: at(5 * MIN) }, NOW)).toBe(0);
  });

  test('accepts ISO strings', () => {
    expect(minutesWaiting({ placed_at: at(-12 * MIN).toISOString() }, NOW)).toBe(12);
  });
});

describe('waitingPoints', () => {
  test.each([
    [0, 0],
    [9, 0],
    [10, 5],
    [19, 5],
    [20, 10],
    [79, 35],
    [80, 40],
    [81, 40],
    [500, 40],
  ])('%i min -> %i pts (cap 40)', (minutes, points) => {
    expect(waitingPoints(minutes)).toBe(points);
  });
});

describe('complexityPoints', () => {
  test.each([
    [0, 0],
    [14, 0],
    [15, 5],
    [30, 10],
    [59, 15],
    [60, 20],
    [61, 20],
    [240, 20],
  ])('%i min -> %i pts (cap 20)', (minutes, points) => {
    expect(complexityPoints(minutes)).toBe(points);
  });
});

describe('promisePoints (exact time difference)', () => {
  test.each([
    ['overdue by 10 min', at(-10 * MIN), 25],
    ['due now', at(0), 25],
    ['due in 30:00', at(30 * MIN), 25],
    ['due in 30:30', at(30 * MIN + 30 * 1000), 15],
    ['due in 60:00', at(60 * MIN), 15],
    ['due in 60:01', at(60 * MIN + 1000), 0],
    ['due in 61 min', at(61 * MIN), 0],
  ])('%s -> %i pts', (_label, promised_at, points) => {
    expect(promisePoints({ promised_at }, NOW)).toBe(points);
  });

  test('null promised_at -> 0 pts', () => {
    expect(promisePoints({ promised_at: null }, NOW)).toBe(0);
  });

  test('missing promised_at -> 0 pts', () => {
    expect(promisePoints({}, NOW)).toBe(0);
  });
});
EOF
cat > compareQueue.test.js <<'EOF'
const { COMPARATORS, compareQueue, sortQueue } = require('../../../src/modules/orders/compareQueue');

const entry = (overrides) => ({
  id: 1,
  score: 50,
  promised_at: '2026-01-15T12:30:00.000Z',
  placed_at: '2026-01-15T11:00:00.000Z',
  ...overrides,
});

describe('compareQueue', () => {
  test('defines comparators in the documented order', () => {
    expect(COMPARATORS.map((c) => c.name)).toEqual([
      'scoreDesc',
      'promisedAtAscNullsLast',
      'placedAtAsc',
      'idAsc',
    ]);
  });

  test('1. higher score first', () => {
    const a = entry({ id: 1, score: 40 });
    const b = entry({ id: 2, score: 60 });
    expect(sortQueue([a, b]).map((e) => e.id)).toEqual([2, 1]);
  });

  test('2. equal score: earlier promised_at first', () => {
    const a = entry({ id: 1, promised_at: '2026-01-15T12:45:00.000Z' });
    const b = entry({ id: 2, promised_at: '2026-01-15T12:15:00.000Z' });
    expect(sortQueue([a, b]).map((e) => e.id)).toEqual([2, 1]);
  });

  test('2. equal score: null promised_at goes last', () => {
    const a = entry({ id: 1, promised_at: null });
    const b = entry({ id: 2, promised_at: '2026-01-15T23:59:00.000Z' });
    expect(sortQueue([a, b]).map((e) => e.id)).toEqual([2, 1]);
    expect(sortQueue([b, a]).map((e) => e.id)).toEqual([2, 1]);
  });

  test('3. equal score and promised_at: earlier placed_at first', () => {
    const a = entry({ id: 1, placed_at: '2026-01-15T11:10:00.000Z' });
    const b = entry({ id: 2, placed_at: '2026-01-15T11:05:00.000Z' });
    expect(sortQueue([a, b]).map((e) => e.id)).toEqual([2, 1]);
  });

  test('3. both promised_at null still falls through to placed_at', () => {
    const a = entry({ id: 1, promised_at: null, placed_at: '2026-01-15T11:10:00.000Z' });
    const b = entry({ id: 2, promised_at: null, placed_at: '2026-01-15T11:05:00.000Z' });
    expect(sortQueue([a, b]).map((e) => e.id)).toEqual([2, 1]);
  });

  test('4. everything equal: lower id first', () => {
    const a = entry({ id: 9 });
    const b = entry({ id: 3 });
    expect(sortQueue([a, b]).map((e) => e.id)).toEqual([3, 9]);
  });

  test('full tie-break sequence orders a mixed list deterministically', () => {
    const list = [
      entry({ id: 7, score: 50, promised_at: null, placed_at: '2026-01-15T11:00:00.000Z' }),
      entry({ id: 6, score: 50, promised_at: '2026-01-15T12:30:00.000Z', placed_at: '2026-01-15T11:01:00.000Z' }),
      entry({ id: 5, score: 50, promised_at: '2026-01-15T12:30:00.000Z', placed_at: '2026-01-15T11:00:00.000Z' }),
      entry({ id: 4, score: 50, promised_at: '2026-01-15T12:30:00.000Z', placed_at: '2026-01-15T11:00:00.000Z' }),
      entry({ id: 3, score: 50, promised_at: '2026-01-15T12:10:00.000Z', placed_at: '2026-01-15T11:59:00.000Z' }),
      entry({ id: 2, score: 70, promised_at: null, placed_at: '2026-01-15T11:59:00.000Z' }),
    ];
    expect(sortQueue(list).map((e) => e.id)).toEqual([2, 3, 4, 5, 6, 7]);
  });

  test('compareQueue returns 0 only for identical keys', () => {
    expect(compareQueue(entry(), entry())).toBe(0);
  });

  test('sortQueue does not mutate its input', () => {
    const list = [entry({ id: 2 }), entry({ id: 1 })];
    sortQueue(list);
    expect(list.map((e) => e.id)).toEqual([2, 1]);
  });
});
