const ERROR_CODES = Object.freeze({
  INVALID_TRANSITION: 'INVALID_TRANSITION',
  UNKNOWN_ACTION: 'UNKNOWN_ACTION',
});

class DomainError extends Error {
  constructor(code, message, details = {}) {
    if (!Object.hasOwn(ERROR_CODES, code)) {
      throw new TypeError(`Unknown DomainError code: ${code}`);
    }
    super(message);
    this.name = 'DomainError';
    this.code = code;
    this.details = details;
  }
}

module.exports = { DomainError, ERROR_CODES };
EOF
cat > priorityRules.js <<'EOF'
const MINUTE_MS = 60 * 1000;

// TODO(assignment): fill in the per-type points from the assignment brief.
// Keys must match the order `type` values used by the API.
const TYPE_POINTS = Object.freeze({});

const VIP_POINTS = 20;

const WAITING = Object.freeze({ pointsPerStep: 5, stepMinutes: 10, cap: 40 });

const COMPLEXITY = Object.freeze({ pointsPerStep: 5, stepMinutes: 15, cap: 20 });

// Evaluated in order; the first bucket whose `maxMinutesUntilDue` is >= the
// exact time remaining wins. Overdue orders (negative remaining) hit the first bucket.
const PROMISE_BUCKETS = Object.freeze([
  Object.freeze({ maxMinutesUntilDue: 30, points: 25 }),
  Object.freeze({ maxMinutesUntilDue: 60, points: 15 }),
]);

module.exports = {
  MINUTE_MS,
  TYPE_POINTS,
  VIP_POINTS,
  WAITING,
  COMPLEXITY,
  PROMISE_BUCKETS,
};
EOF
cat > priority.js <<'EOF'
const {
  MINUTE_MS,
  WAITING,
  COMPLEXITY,
  PROMISE_BUCKETS,
} = require('./priorityRules');

const toMs = (value) => (value instanceof Date ? value.getTime() : new Date(value).getTime());

const steppedPoints = (minutes, { pointsPerStep, stepMinutes, cap }) =>
  Math.min(Math.floor(Math.max(0, minutes) / stepMinutes) * pointsPerStep, cap);

function minutesWaiting(order, now) {
  const elapsedMs = toMs(now) - toMs(order.placed_at);
  return Math.max(0, Math.floor(elapsedMs / MINUTE_MS));
}

const waitingPoints = (minutes) => steppedPoints(minutes, WAITING);

const complexityPoints = (minutes) => steppedPoints(minutes, COMPLEXITY);

function promisePoints(order, now) {
  if (order.promised_at == null) return 0;
  const remainingMs = toMs(order.promised_at) - toMs(now);
  const bucket = PROMISE_BUCKETS.find((b) => remainingMs <= b.maxMinutesUntilDue * MINUTE_MS);
  return bucket ? bucket.points : 0;
}

// TODO(assignment): scoreBreakdown(order, now) and computePriority(order, now)
// need the type points and the order field names for type / VIP / complexity.

module.exports = {
  toMs,
  minutesWaiting,
  waitingPoints,
  complexityPoints,
  promisePoints,
};
EOF
cat > compareQueue.js <<'EOF'
const { toMs } = require('./priority');

function scoreDesc(a, b) {
  return b.score - a.score;
}

function promisedAtAscNullsLast(a, b) {
  const aNull = a.promised_at == null;
  const bNull = b.promised_at == null;
  if (aNull && bNull) return 0;
  if (aNull) return 1;
  if (bNull) return -1;
  return toMs(a.promised_at) - toMs(b.promised_at);
}

function placedAtAsc(a, b) {
  return toMs(a.placed_at) - toMs(b.placed_at);
}

function idAsc(a, b) {
  if (typeof a.id === 'number' && typeof b.id === 'number') return a.id - b.id;
  return String(a.id).localeCompare(String(b.id));
}

const COMPARATORS = Object.freeze([scoreDesc, promisedAtAscNullsLast, placedAtAsc, idAsc]);

function compareQueue(a, b) {
  for (const comparator of COMPARATORS) {
    const result = comparator(a, b);
    if (result !== 0) return result;
  }
  return 0;
}

const sortQueue = (entries) => [...entries].sort(compareQueue);

module.exports = { COMPARATORS, compareQueue, sortQueue };
EOF
