cat > priority.js <<'EOF'
const {
  MINUTE_MS,
  TYPE_POINTS,
  VIP_POINTS,
  WAITING,
  COMPLEXITY,
  PROMISE_BUCKETS,
} = require('./priorityRules');

const toMs = (value) => (value instanceof Date ? value.getTime() : new Date(value).getTime());

const steppedPoints = (minutes, { pointsPerStep, stepMinutes, cap }) =>
  Math.min(Math.floor(Math.max(0, minutes) / stepMinutes) * pointsPerStep, cap);

function minutesWaiting(order, now) {
  const elapsedMs = toMs(now) - toMs(order.placed_at);
  return Math.max(0, Math.floor(elapsedMs / MINUTE_MS));
}

// Items are plain { prep_time_minutes, quantity } objects; the repository flattens them.
function totalPrepMinutes(items = []) {
  return items.reduce((sum, item) => sum + item.prep_time_minutes * item.quantity, 0);
}

function typePoints(type) {
  if (!Object.hasOwn(TYPE_POINTS, type)) {
    throw new TypeError(`Unknown order type: ${type}`);
  }
  return TYPE_POINTS[type];
}

const waitingPoints = (minutes) => steppedPoints(minutes, WAITING);

const complexityPoints = (minutes) => steppedPoints(minutes, COMPLEXITY);

// Unlike waiting time, the promise window uses the exact difference, not whole minutes.
function promisePoints(order, now) {
  if (order.promised_at == null) return 0;
  const remainingMs = toMs(order.promised_at) - toMs(now);
  const bucket = PROMISE_BUCKETS.find((b) => remainingMs <= b.maxMinutesUntilDue * MINUTE_MS);
  return bucket ? bucket.points : 0;
}

function scoreBreakdown(order, now) {
  const breakdown = {
    type: typePoints(order.type),
    vip: order.is_vip === true ? VIP_POINTS : 0,
    waiting: waitingPoints(minutesWaiting(order, now)),
    promise: promisePoints(order, now),
    complexity: complexityPoints(totalPrepMinutes(order.items)),
  };
  const total = Object.values(breakdown).reduce((sum, points) => sum + points, 0);
  return { ...breakdown, total };
}

const computePriority = (order, now) => scoreBreakdown(order, now).total;

module.exports = {
  computePriority,
  scoreBreakdown,
  minutesWaiting,
  totalPrepMinutes,
  waitingPoints,
  complexityPoints,
  promisePoints,
  toMs,
};
EOF
cat > transitions.js <<'EOF'
const { DomainError, ERROR_CODES } = require('./errors');

const STATUSES = Object.freeze(['received', 'preparing', 'ready', 'picked_up', 'cancelled']);

const ACTIVE_STATUSES = Object.freeze(['received', 'preparing']);

const TERMINAL_STATUSES = Object.freeze(['picked_up', 'cancelled']);

// Single source of truth for the state machine. Key order is the order
// availableActions() returns, so the UI lists "start" before "cancel".
const ACTIONS = Object.freeze({
  start: Object.freeze({ from: Object.freeze(['received']), to: 'preparing' }),
  cancel: Object.freeze({ from: Object.freeze(['received']), to: 'cancelled' }),
  ready: Object.freeze({ from: Object.freeze(['preparing']), to: 'ready' }),
  pickup: Object.freeze({ from: Object.freeze(['ready']), to: 'picked_up' }),
});

function availableActions(status) {
  return Object.keys(ACTIONS).filter((action) => ACTIONS[action].from.includes(status));
}

function nextStatus(status, action) {
  if (!Object.hasOwn(ACTIONS, action)) {
    throw new DomainError(ERROR_CODES.UNKNOWN_ACTION, `Unknown action "${action}"`, { action });
  }
  const { from, to } = ACTIONS[action];
  if (!from.includes(status)) {
    throw new DomainError(
      ERROR_CODES.INVALID_TRANSITION,
      `Cannot ${action} an order that is ${status}`,
      { status, action, allowedActions: availableActions(status) },
    );
  }
  return to;
}

module.exports = {
  STATUSES,
  ACTIVE_STATUSES,
  TERMINAL_STATUSES,
  ACTIONS,
  availableActions,
  nextStatus,
};
EOF
