  return bucket ? bucket.points : 0;
}

function scoreBreakdown(order, now) {
  const breakdown = {
    type: typePoints(order.type),
    vip: order.is_vip === true ? VIP_POINTS : 0,
    waiting: waitingPoints(minutesWaiting(order, now)),
    promise: promisePoints(order, now),
    complexity: complexityPoints(totalPrepMinutes(order.items)),
  };
  const total = Object.values(breakdown).reduce((sum, points) => sum + points, 0);
  return { ...breakdown, total };
}

const computePriority = (order, now) => scoreBreakdown(order, now).total;

module.exports = {
  computePriority,
  scoreBreakdown,
  minutesWaiting,
  totalPrepMinutes,
  waitingPoints,
  complexityPoints,
  promisePoints,
  toMs,
};
