'use strict';

// Every timestamp is relative to the moment the seed runs (UTC), so the demo never goes stale.
// Expected scores are noted per order; they hold for as long as the demo stays in the same
// minute buckets (the tie pair is designed to stay tied indefinitely).

const MENU = [
  { name: 'Caesar Salad', category: 'starter', prep_time_minutes: 10 },
  { name: 'Garlic Bread', category: 'starter', prep_time_minutes: 5 },
  { name: 'Grilled Salmon', category: 'main_course', prep_time_minutes: 20 },
  { name: 'Margherita Pizza', category: 'main_course', prep_time_minutes: 12 },
  { name: 'Ribeye Steak', category: 'main_course', prep_time_minutes: 25 },
  { name: 'Mushroom Risotto', category: 'main_course', prep_time_minutes: 18 },
  { name: 'Tiramisu', category: 'dessert', prep_time_minutes: 5 },
  { name: 'Lemonade', category: 'drink', prep_time_minutes: 2 },
];

const MINUTE_MS = 60 * 1000;

function buildOrders(now) {
  const ago = (minutes) => new Date(now - minutes * MINUTE_MS);
  const inMinutes = (minutes) => new Date(now + minutes * MINUTE_MS);
  // The tie pair shares one placed_at so their wait-time points always move together.
  const tiePlacedAt = ago(15);

  return [
    {
      // Wait-time cap: 95 min -> 45 uncapped, capped to 40. 30 + 40 + 0 + 0 + 0 = 70.
      customer_name: 'Ana Souza', type: 'dine_in', is_vip: false, status: 'received',
      placed_at: ago(95), promised_at: null,
      items: [['Caesar Salad', 1]],
    },
    {
      // Complexity cap: 2x25 + 18 = 68 prep min -> 20. 20 + 0 + 0 + 15 + 20 = 55.
      customer_name: 'Bruno Lima', type: 'takeout', is_vip: false, status: 'received',
      placed_at: ago(5), promised_at: inMinutes(50),
      items: [['Ribeye Steak', 2], ['Mushroom Risotto', 1]],
    },
    {
      // Tie pair (first): 20 + 0 + 5 + 25 + 0 = 50. Earlier promised_at, so ranks first.
      customer_name: 'Carla Dias', type: 'takeout', is_vip: false, status: 'received',
      placed_at: tiePlacedAt, promised_at: inMinutes(10),
      items: [['Margherita Pizza', 1]],
    },
    {
      // Tie pair (second): same score, same placed_at, later promised_at.
      // Both promises stay in the <=30 min bucket (overdue included), so the tie never breaks.
      customer_name: 'Diego Rocha', type: 'takeout', is_vip: false, status: 'received',
      placed_at: tiePlacedAt, promised_at: inMinutes(25),
      items: [['Margherita Pizza', 1]],
    },
    {
      // Delivery VIP with a tight promise: 10 + 20 + 5 + 25 + 0 = 60, above most dine_in orders.
      customer_name: 'Eva Martins', type: 'delivery', is_vip: true, status: 'received',
      placed_at: ago(12), promised_at: inMinutes(20),
      items: [['Garlic Bread', 1], ['Lemonade', 1]],
    },
    {
      // Preparing, dine_in: 30 + 0 + 10 + 0 + 5 = 45.
      customer_name: 'Felipe Costa', type: 'dine_in', is_vip: false, status: 'preparing',
      placed_at: ago(20), promised_at: null,
      items: [['Grilled Salmon', 1], ['Tiramisu', 1]],
    },
    {
      // Preparing, VIP takeout due soon: 20 + 20 + 10 + 25 + 5 = 80.
      customer_name: 'Gabriela Alves', type: 'takeout', is_vip: true, status: 'preparing',
      placed_at: ago(25), promised_at: inMinutes(5),
      items: [['Mushroom Risotto', 1]],
    },
    {
      // Ready: not part of the active queue.
      customer_name: 'Hugo Ferreira', type: 'dine_in', is_vip: false, status: 'ready',
      placed_at: ago(40), promised_at: null,
      items: [['Grilled Salmon', 2]],
    },
    {
      // Terminal: picked_up.
      customer_name: 'Iris Nunes', type: 'delivery', is_vip: false, status: 'picked_up',
      placed_at: ago(70), promised_at: ago(30),
      items: [['Margherita Pizza', 2]],
    },
    {
      // Terminal: cancelled.
      customer_name: 'João Pereira', type: 'takeout', is_vip: true, status: 'cancelled',
      placed_at: ago(30), promised_at: inMinutes(15),
      items: [['Tiramisu', 2]],
    },
  ];
}

module.exports = {
  async up(queryInterface) {
    const now = Date.now();
    const createdAt = new Date(now);
    const stamps = { created_at: createdAt, updated_at: createdAt };

    await queryInterface.sequelize.transaction(async (transaction) => {
      const menuRows = await queryInterface.bulkInsert(
        'menu_items',
        MENU.map((item) => ({ ...item, ...stamps })),
        { transaction, returning: true },
      );
      const menuIdByName = new Map(menuRows.map((row) => [row.name, row.id]));

      const orders = buildOrders(now);
      const orderRows = await queryInterface.bulkInsert(
        'orders',
        orders.map(({ items, ...order }) => ({ ...order, ...stamps })),
        { transaction, returning: true },
      );

      const orderItems = orderRows.flatMap((row, index) =>
        orders[index].items.map(([name, quantity]) => ({
          order_id: row.id,
          menu_item_id: menuIdByName.get(name),
          quantity,
          ...stamps,
        })),
      );
      await queryInterface.bulkInsert('order_items', orderItems, { transaction });
    });
  },

  async down(queryInterface) {
    await queryInterface.sequelize.transaction(async (transaction) => {
