const { Order, OrderItem, MenuItem } = require('../schema/models');

const ITEMS_INCLUDE = [
  { model: OrderItem, as: 'items', include: [{ model: MenuItem, as: 'menu_item' }] },
];
const ITEMS_ORDER = [[{ model: OrderItem, as: 'items' }, 'id', 'ASC']];

// Flattens a Sequelize row into the plain shape the domain modules consume,
// so nothing above this layer depends on model instances or association names.
function toDomain(row) {
  const order = row.get({ plain: true });
  return {
    id: order.id,
    customer_name: order.customer_name,
    type: order.type,
    status: order.status,
    is_vip: order.is_vip,
    placed_at: order.placed_at,
    promised_at: order.promised_at,
    items: order.items.map((item) => ({
      menu_item_id: item.menu_item_id,
      name: item.menu_item.name,
      category: item.menu_item.category,
      prep_time_minutes: item.menu_item.prep_time_minutes,
      quantity: item.quantity,
    })),
  };
}

async function findByStatuses(statuses) {
  const rows = await Order.findAll({
    where: { status: statuses },
    include: ITEMS_INCLUDE,
    order: [['id', 'ASC'], ...ITEMS_ORDER],
  });
  return rows.map(toDomain);
}

async function findById(id) {
  const row = await Order.findByPk(id, { include: ITEMS_INCLUDE, order: ITEMS_ORDER });
  return row ? toDomain(row) : null;
}

// Compare-and-set: the WHERE on the current status makes the check and the write one
// statement, so two concurrent actions on the same order cannot both succeed.
async function updateStatusIf(id, from, to) {
  const [affected] = await Order.update({ status: to }, { where: { id, status: from } });
  return affected === 1;
}

module.exports = { findByStatuses, findById, updateStatusIf };
