cat > endpoints/errorHandler.js <<'EOF'
const { DomainError } = require('../modules/orders/errors');

const HTTP_STATUS_BY_CODE = Object.freeze({
  INVALID_TRANSITION: 409,
  ORDER_NOT_FOUND: 404,
  UNKNOWN_ACTION: 404,
  INVALID_ORDER_ID: 400,
  INVALID_STATUS_FILTER: 400,
  INVALID_JSON: 400,
  ROUTE_NOT_FOUND: 404,
  INTERNAL_ERROR: 500,
});

function sendError(res, code, message, details) {
  const body = { error: { code, message } };
  if (details !== undefined) body.error.details = details;
  res.status(HTTP_STATUS_BY_CODE[code] ?? 500).json(body);
}

function notFoundHandler(req, res) {
  sendError(res, 'ROUTE_NOT_FOUND', `No route for ${req.method} ${req.path}`, {
    method: req.method,
    path: req.path,
  });
}

function createErrorHandler({ logger }) {
  // Express recognises error middleware by its four-argument signature.
  // eslint-disable-next-line no-unused-vars
  return function errorHandler(err, req, res, next) {
    if (res.headersSent) return next(err);
    if (err instanceof DomainError) return sendError(res, err.code, err.message, err.details);
    if (err.type === 'entity.parse.failed') {
      return sendError(res, 'INVALID_JSON', 'Request body is not valid JSON');
    }
    logger.error(err);
    return sendError(res, 'INTERNAL_ERROR', 'Unexpected server error');
  };
}

module.exports = { HTTP_STATUS_BY_CODE, notFoundHandler, createErrorHandler };
