const { DomainError, ERROR_CODES } = require('./errors');

const MAX_DB_INTEGER = 2147483647;

function parseOrderId(raw) {
  const text = String(raw);
  const id = Number(text);
  if (!/^[1-9]\d*$/.test(text) || id > MAX_DB_INTEGER) {
    throw new DomainError(ERROR_CODES.INVALID_ORDER_ID, `Invalid order id "${text}"`, { id: text });
  }
  return id;
}

function resolveStatuses(statusFilter) {
  if (statusFilter === undefined) return ACTIVE_STATUSES;
  if (typeof statusFilter === 'string' && ACTIVE_STATUSES.includes(statusFilter)) return [statusFilter];
  throw new DomainError(
    ERROR_CODES.INVALID_STATUS_FILTER,
    `Status filter must be one of: ${ACTIVE_STATUSES.join(', ')}`,
    { status: statusFilter, allowed: ACTIVE_STATUSES },
  );
}

const orderNotFound = (id) =>
  new DomainError(ERROR_CODES.ORDER_NOT_FOUND, `Order ${id} not found`, { id });

const withActions = (order) => ({ ...order, available_actions: availableActions(order.status) });

function createOrdersService({ orderRepository }) {
  async function getQueue({ statusFilter, now }) {
    if (!(now instanceof Date) || Number.isNaN(now.getTime())) {
      throw new TypeError('getQueue requires `now` as a valid Date');
    }
    const orders = await orderRepository.findByStatuses(resolveStatuses(statusFilter));
    const entries = orders.map((order) => {
      const breakdown = scoreBreakdown(order, now);
      return {
        ...withActions(order),
        score: breakdown.total,
        breakdown,
        minutes_waiting: minutesWaiting(order, now),
      };
    });
    return sortQueue(entries);
  }

  async function applyAction({ orderId, action }) {
    const id = parseOrderId(orderId);
    assertKnownAction(action);

    const order = await orderRepository.findById(id);
    if (!order) throw orderNotFound(id);

    const to = nextStatus(order.status, action);
    const updated = await orderRepository.updateStatusIf(id, order.status, to);
    if (!updated) {
      // Another request changed the status between our read and write. The state machine
      // has no cycles, so the action is no longer legal; report the status that won.
      const current = await orderRepository.findById(id);
      if (!current) throw orderNotFound(id);
      throw invalidTransitionError(current.status, action);
    }

    return withActions(await orderRepository.findById(id));
  }

  return { getQueue, applyAction };
}

module.exports = { createOrdersService, parseOrderId };
