const { createOrdersService, parseOrderId } = require('../../../src/modules/orders/ordersService');
const { DomainError } = require('../../../src/modules/orders/errors');

const NOW = new Date('2026-06-15T12:00:00Z');

const order = (overrides) => ({
  id: 1,
  customer_name: 'Test',
  type: 'dine_in',
  status: 'received',
  is_vip: false,
  placed_at: new Date('2026-06-15T11:30:00Z'),
  promised_at: null,
  items: [{ menu_item_id: 1, name: 'Soup', category: 'starter', prep_time_minutes: 10, quantity: 1 }],
  ...overrides,
});

// In-memory repository with the same contract as orderRepository.
function fakeRepository(rows) {
  const store = new Map(rows.map((row) => [row.id, { ...row }]));
  return {
    findByStatuses: jest.fn(async (statuses) => [...store.values()].filter((o) => statuses.includes(o.status))),
    findById: jest.fn(async (id) => (store.has(id) ? { ...store.get(id) } : null)),
    updateStatusIf: jest.fn(async (id, from, to) => {
      const row = store.get(id);
      if (!row || row.status !== from) return false;
      row.status = to;
      return true;
    }),
    store,
  };
}

async function expectCode(promise, code) {
  const err = await promise.then(() => null, (e) => e);
  expect(err).toBeInstanceOf(DomainError);
  expect(err.code).toBe(code);
  return err;
}

describe('getQueue', () => {
  test('default queue asks the repository for received + preparing only', async () => {
    const repo = fakeRepository([]);
    await createOrdersService({ orderRepository: repo }).getQueue({ now: NOW });
    expect(repo.findByStatuses).toHaveBeenCalledWith(['received', 'preparing']);
  });

  test('cancelled, picked_up and ready orders are not in the default queue', async () => {
    const repo = fakeRepository([
      order({ id: 1, status: 'received' }),
      order({ id: 2, status: 'preparing' }),
      order({ id: 3, status: 'ready' }),
      order({ id: 4, status: 'picked_up' }),
      order({ id: 5, status: 'cancelled' }),
    ]);
    const queue = await createOrdersService({ orderRepository: repo }).getQueue({ now: NOW });
    expect(queue.map((o) => o.id).sort()).toEqual([1, 2]);
  });

  test.each(['received', 'preparing'])('status filter %s is passed through', async (status) => {
    const repo = fakeRepository([]);
    await createOrdersService({ orderRepository: repo }).getQueue({ statusFilter: status, now: NOW });
    expect(repo.findByStatuses).toHaveBeenCalledWith([status]);
  });

  test.each([['ready'], ['cancelled'], [''], [['received', 'preparing']], ['RECEIVED']])(
    'status filter %j is rejected with INVALID_STATUS_FILTER',
    async (statusFilter) => {
      const repo = fakeRepository([]);
      await expectCode(
        createOrdersService({ orderRepository: repo }).getQueue({ statusFilter, now: NOW }),
        'INVALID_STATUS_FILTER',
      );
      expect(repo.findByStatuses).not.toHaveBeenCalled();
    },
  );

  test('adds score, breakdown, minutes_waiting and available_actions, sorted by score', async () => {
    const repo = fakeRepository([
      order({ id: 1, type: 'delivery' }),
      order({ id: 2, type: 'dine_in', status: 'preparing' }),
    ]);
    const queue = await createOrdersService({ orderRepository: repo }).getQueue({ now: NOW });
    expect(queue.map((o) => o.id)).toEqual([2, 1]);
    expect(queue[0]).toMatchObject({
      score: 45,
      breakdown: { type: 30, vip: 0, waiting: 15, promise: 0, complexity: 0, total: 45 },
      minutes_waiting: 30,
      available_actions: ['ready'],
    });
    expect(queue[1].available_actions).toEqual(['start', 'cancel']);
  });

  test('requires an injected now', async () => {
    const service = createOrdersService({ orderRepository: fakeRepository([]) });
    await expect(service.getQueue({})).rejects.toThrow(TypeError);
  });
});

describe('applyAction', () => {
  test('applies a legal transition and returns the updated order', async () => {
    const repo = fakeRepository([order({ id: 7 })]);
    const result = await createOrdersService({ orderRepository: repo }).applyAction({ orderId: '7', action: 'start' });
    expect(repo.updateStatusIf).toHaveBeenCalledWith(7, 'received', 'preparing');
    expect(result).toMatchObject({ id: 7, status: 'preparing', available_actions: ['ready'] });
  });

  test('starting an already preparing order is INVALID_TRANSITION and writes nothing', async () => {
    const repo = fakeRepository([order({ id: 7, status: 'preparing' })]);
    const err = await expectCode(
      createOrdersService({ orderRepository: repo }).applyAction({ orderId: '7', action: 'start' }),
      'INVALID_TRANSITION',
    );
    expect(err.details).toEqual({ status: 'preparing', action: 'start', allowedActions: ['ready'] });
    expect(repo.updateStatusIf).not.toHaveBeenCalled();
  });

  test('missing order is ORDER_NOT_FOUND', async () => {
    const repo = fakeRepository([]);
    await expectCode(
      createOrdersService({ orderRepository: repo }).applyAction({ orderId: '99', action: 'start' }),
      'ORDER_NOT_FOUND',
    );
  });

  test('unknown action is rejected before touching the repository', async () => {
    const repo = fakeRepository([order({ id: 7 })]);
    await expectCode(
      createOrdersService({ orderRepository: repo }).applyAction({ orderId: '7', action: 'teleport' }),
      'UNKNOWN_ACTION',
    );
    expect(repo.findById).not.toHaveBeenCalled();
  });

  test('losing a race reports INVALID_TRANSITION against the status that won', async () => {
    const repo = fakeRepository([order({ id: 7 })]);
    // Simulate a concurrent cancel landing between our read and our conditional write.
    repo.updateStatusIf.mockImplementationOnce(async () => {
      repo.store.get(7).status = 'cancelled';
      return false;
    });
    const err = await expectCode(
      createOrdersService({ orderRepository: repo }).applyAction({ orderId: '7', action: 'start' }),
      'INVALID_TRANSITION',
    );
    expect(err.details).toEqual({ status: 'cancelled', action: 'start', allowedActions: [] });
  });

  test('order deleted during the race is ORDER_NOT_FOUND', async () => {
    const repo = fakeRepository([order({ id: 7 })]);
    repo.updateStatusIf.mockImplementationOnce(async () => {
      repo.store.delete(7);
      return false;
    });
    await expectCode(
      createOrdersService({ orderRepository: repo }).applyAction({ orderId: '7', action: 'start' }),
      'ORDER_NOT_FOUND',
    );
  });
});

describe('parseOrderId', () => {
  test.each([['1', 1], ['42', 42], [42, 42], ['2147483647', 2147483647]])('%j -> %j', (raw, id) => {
    expect(parseOrderId(raw)).toBe(id);
  });

  test.each(['0', '-1', '1.5', 'abc', '01', '1e3', ' 1', '2147483648', ''])('%j is INVALID_ORDER_ID', (raw) => {
    expect(() => parseOrderId(raw)).toThrow(expect.objectContaining({ code: 'INVALID_ORDER_ID' }));
  });
});
