  test.each(['ready', 'cancelled', 'bogus', ''])('status=%j is rejected with 400 INVALID_STATUS_FILTER', async (status) => {
    await createMixedQueue();
    const res = await getQueue(`?status=${status}`);
    expect(res.status).toBe(400);
    expect(res.body.error.code).toBe('INVALID_STATUS_FILTER');
  });

  test('promised_at breaks a score tie; null promised_at goes last; id is not what decides', async () => {
    const placed_at = minutesAgo(15);
    const fields = { type: 'takeout', placed_at };
    // Created in reverse of the expected order, so id ascending would give the wrong answer.
    const noPromise = await createOrder({ ...fields, customer_name: 'No promise' }, [[menu.pizza, 1]]);
    const later = await createOrder({ ...fields, customer_name: 'Later', promised_at: minutesFromNow(25) }, [[menu.pizza, 1]]);
    const sooner = await createOrder({ ...fields, customer_name: 'Sooner', promised_at: minutesFromNow(10) }, [[menu.pizza, 1]]);
    // Same score without the promise points, so give the no-promise order a different type to keep the tie honest.
    // takeout + wait 5 + promise 25 = 50 for sooner/later.
    const res = await getQueue();
    const byId = Object.fromEntries(res.body.orders.map((o) => [o.id, o.score]));
    expect(byId[sooner.id]).toBe(50);
    expect(byId[later.id]).toBe(50);
    expect(ids(res)).toEqual([sooner.id, later.id, noPromise.id]);
  });

  test('every order includes available_actions for its status', async () => {
    const { exampleA, exampleB } = await createMixedQueue();
    const res = await getQueue();
    const actions = Object.fromEntries(res.body.orders.map((o) => [o.id, o.available_actions]));
    expect(actions[exampleA.id]).toEqual(['start', 'cancel']);
    expect(actions[exampleB.id]).toEqual(['ready']);
  });

  test('empty queue returns an empty list', async () => {
    const res = await getQueue();
    expect(res.status).toBe(200);
    expect(res.body).toEqual({ generated_at: NOW.toISOString(), orders: [] });
  });
});

describe('POST /orders/:id/:action — legal transitions are persisted', () => {
  test('received -> preparing -> ready -> picked_up', async () => {
    const { id } = await createOrder({}, [[menu.salad, 1]]);

    for (const [action, status, available] of [
      ['start', 'preparing', ['ready']],
      ['ready', 'ready', ['pickup']],
      ['pickup', 'picked_up', []],
    ]) {
      const res = await act(id, action);
      expect(res.status).toBe(200);
      expect(res.body.order).toMatchObject({ id, status, available_actions: available });
      expect((await readOrderRow(id)).status).toBe(status);
    }
  });

  test('received -> cancelled, and the order leaves the default queue', async () => {
    const { id } = await createOrder({}, [[menu.salad, 1]]);
    expect(ids(await getQueue())).toContain(id);

    const res = await act(id, 'cancel');

    expect(res.status).toBe(200);
    expect(res.body.order).toMatchObject({ id, status: 'cancelled', available_actions: [] });
    expect((await readOrderRow(id)).status).toBe('cancelled');
    expect(ids(await getQueue())).not.toContain(id);
  });

  test('ready order leaves the active queue', async () => {
    const { id } = await createOrder({ status: 'preparing' }, [[menu.salad, 1]]);
    await act(id, 'ready');
    expect(ids(await getQueue())).not.toContain(id);
  });
});

describe('POST /orders/:id/:action — illegal transitions', () => {
  test('starting an already preparing order returns 409 and changes nothing', async () => {
    const { id } = await createOrder({ status: 'preparing' }, [[menu.salad, 1]]);
    const before = await readOrderRow(id);

    const res = await act(id, 'start');

    expect(res.status).toBe(409);
    expect(res.body.error).toEqual({
      code: 'INVALID_TRANSITION',
      message: 'Cannot start an order that is preparing',
      details: { status: 'preparing', action: 'start', allowedActions: ['ready'] },
    });
    expect(await readOrderRow(id)).toEqual(before);
  });

  test.each([
    ['received', 'ready'],
    ['received', 'pickup'],
    ['preparing', 'pickup'],
  ])('skipping a step: %s + %s returns 409 and changes nothing', async (status, action) => {
    const { id } = await createOrder({ status }, [[menu.salad, 1]]);
    const before = await readOrderRow(id);

    const res = await act(id, action);

    expect(res.status).toBe(409);
    expect(res.body.error.code).toBe('INVALID_TRANSITION');
    expect(await readOrderRow(id)).toEqual(before);
  });

  test.each(['picked_up', 'cancelled'])('nothing leaves terminal status %s', async (status) => {
    const { id } = await createOrder({ status }, [[menu.salad, 1]]);
    const before = await readOrderRow(id);

    for (const action of ['start', 'cancel', 'ready', 'pickup']) {
      const res = await act(id, action);
      expect(res.status).toBe(409);
      expect(res.body.error).toMatchObject({ code: 'INVALID_TRANSITION', details: { status, allowedActions: [] } });
    }
    expect(await readOrderRow(id)).toEqual(before);
  });

  test('cancelling a preparing order is rejected (cancel is only allowed from received)', async () => {
    const { id } = await createOrder({ status: 'preparing' }, [[menu.salad, 1]]);
    const res = await act(id, 'cancel');
    expect(res.status).toBe(409);
    expect((await readOrderRow(id)).status).toBe('preparing');
  });
});

describe('invalid requests and missing resources', () => {
  test.each([
    ['abc', 'start', 400, 'INVALID_ORDER_ID'],
    ['0', 'start', 400, 'INVALID_ORDER_ID'],
    ['-1', 'start', 400, 'INVALID_ORDER_ID'],
    ['1.5', 'start', 400, 'INVALID_ORDER_ID'],
    ['2147483648', 'start', 400, 'INVALID_ORDER_ID'],
    ['999999', 'start', 404, 'ORDER_NOT_FOUND'],
  ])('POST /orders/%s/%s -> %i %s', async (id, action, status, code) => {
    const res = await act(id, action);
    expect(res.status).toBe(status);
    expect(res.body.error.code).toBe(code);
  });

  test('unknown action on an existing order -> 404 UNKNOWN_ACTION, order unchanged', async () => {
    const { id } = await createOrder({}, [[menu.salad, 1]]);
    const before = await readOrderRow(id);
    const res = await act(id, 'teleport');
    expect(res.status).toBe(404);
    expect(res.body.error.code).toBe('UNKNOWN_ACTION');
    expect(await readOrderRow(id)).toEqual(before);
  });

  test('malformed JSON body -> 400 INVALID_JSON', async () => {
    const { id } = await createOrder({}, [[menu.salad, 1]]);
    const res = await request(app)
      .post(`/orders/${id}/start`)
      .set('Content-Type', 'application/json')
      .send('{"oops"');
    expect(res.status).toBe(400);
    expect(res.body.error.code).toBe('INVALID_JSON');
    expect((await readOrderRow(id)).status).toBe('received');
  });

  test.each([
    ['get', '/orders'],
    ['get', '/orders/1/start'],
    ['put', '/orders/queue'],
  ])('%s %s -> 404 ROUTE_NOT_FOUND', async (method, path) => {
    const res = await request(app)[method](path);
    expect(res.status).toBe(404);
    expect(res.body.error.code).toBe('ROUTE_NOT_FOUND');
  });
});
