const { execSync } = require('child_process');
const path = require('path');

// Rebuilds kitchen_queue_test from the real migrations before the integration suite.
// Never touches the development database: NODE_ENV is forced to "test".
function sequelizeCli(cmd) {
  try {
    execSync(`npx sequelize-cli ${cmd}`, {
      cwd: path.resolve(__dirname, '../..'),
      env: { ...process.env, NODE_ENV: 'test' },
      stdio: 'pipe',
    });
  } catch (err) {
    const output = `${err.stdout ?? ''}${err.stderr ?? ''}`;
    const wrapped = new Error(
      `sequelize-cli ${cmd} failed against the test database.\n` +
        'Is PostgreSQL running? Start it with `docker compose up -d`.\n\n' +
        output.trim(),
    );
    wrapped.output = output;
    throw wrapped;
  }
}

module.exports = async () => {
  try {
    sequelizeCli('db:create');
  } catch (err) {
    if (!err.output.includes('already exists')) throw err;
  }
  sequelizeCli('db:migrate:undo:all');
  sequelizeCli('db:migrate');
};
EOF
