// Mirrors the API's response shapes. The UI never derives score, order or legal actions itself.

export type OrderType = 'dine_in' | 'takeout' | 'delivery';
export type OrderStatus = 'received' | 'preparing' | 'ready' | 'picked_up' | 'cancelled';
export type OrderAction = 'start' | 'cancel' | 'ready' | 'pickup';
export type QueueFilter = 'active' | 'received' | 'preparing';

export interface OrderItem {
  menu_item_id: number;
  name: string;
  category: string;
  prep_time_minutes: number;
  quantity: number;
}

export interface Order {
  id: number;
  customer_name: string;
  type: OrderType;
  status: OrderStatus;
  is_vip: boolean;
  placed_at: string;
  promised_at: string | null;
  items: OrderItem[];
  items_summary: string;
  available_actions: OrderAction[];
}

export interface QueueOrder extends Order {
  score: number;
  score_breakdown: Record<string, number>;
  minutes_waiting: number;
}

export interface QueueResponse {
  generated_at: string;
  orders: QueueOrder[];
}

export interface ApiErrorBody {
  code: string;
  message: string;
  details?: unknown;
}
EOF
cat > src/api/client.ts <<'EOF'
import type { ApiErrorBody, Order, OrderAction, QueueFilter, QueueResponse } from './types';

export class ApiError extends Error {
  readonly code: string;
  readonly status: number | null;
  readonly details?: unknown;

  constructor({ code, message, details }: ApiErrorBody, status: number | null) {
    super(message);
    this.name = 'ApiError';
    this.code = code;
    this.status = status;
    this.details = details;
  }
}

async function request<T>(path: string, init?: RequestInit): Promise<T> {
  let res: Response;
  try {
    res = await fetch(`/api${path}`, { headers: { Accept: 'application/json' }, ...init });
  } catch (err) {
    if (err instanceof DOMException && err.name === 'AbortError') throw err;
    throw new ApiError(
      { code: 'NETWORK_ERROR', message: 'The kitchen API did not respond. Check that it is running on port 4000.' },
      null,
    );
  }

  const body = await res.json().catch(() => null);
  if (!res.ok) {
    const error = body?.error as ApiErrorBody | undefined;
    throw new ApiError(
      error?.code
        ? error
        : { code: `HTTP_${res.status}`, message: `The API answered ${res.status} without an error body.` },
      res.status,
    );
  }
  return body as T;
}

export function fetchQueue(filter: QueueFilter, signal?: AbortSignal): Promise<QueueResponse> {
  const query = filter === 'active' ? '' : `?status=${filter}`;
  return request<QueueResponse>(`/orders/queue${query}`, { signal });
}

export async function postAction(orderId: number, action: OrderAction): Promise<Order> {
  const body = await request<{ order: Order }>(`/orders/${orderId}/${action}`, { method: 'POST' });
  return body.order;
}
