import type { OrderAction, OrderStatus, OrderType } from './api/types';

// Presentation vocabulary only. Which actions exist for an order comes from the API.
export const ACTION_LABEL: Record<OrderAction, string> = {
  start: 'Start',
  ready: 'Mark ready',
  pickup: 'Picked up',
  cancel: 'Cancel',
};

export const STATUS_LABEL: Record<OrderStatus, string> = {
  received: 'Received',
  preparing: 'Preparing',
  ready: 'Ready',
  picked_up: 'Picked up',
  cancelled: 'Cancelled',
};

export const TYPE_LABEL: Record<OrderType, string> = {
  dine_in: 'Dine-in',
  takeout: 'Takeout',
  delivery: 'Delivery',
};

export const ERROR_TITLE: Record<string, string> = {
  INVALID_TRANSITION: "That step isn't allowed",
  ORDER_NOT_FOUND: 'Order not found',
  UNKNOWN_ACTION: 'Unknown action',
  INVALID_ORDER_ID: 'Invalid order',
  INVALID_STATUS_FILTER: 'Invalid filter',
  INVALID_JSON: 'Malformed request',
  ROUTE_NOT_FOUND: 'Unknown API route',
  INTERNAL_ERROR: 'The API hit an error',
  NETWORK_ERROR: "Can't reach the kitchen API",
};

export const errorTitle = (code: string) => ERROR_TITLE[code] ?? 'Request failed';

const clockFormat = new Intl.DateTimeFormat(undefined, { hour: '2-digit', minute: '2-digit', hour12: false });
const clockWithSeconds = new Intl.DateTimeFormat(undefined, {
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false,
});

export const formatClock = (iso: string) => clockFormat.format(new Date(iso));
export const formatClockSeconds = (iso: string) => clockWithSeconds.format(new Date(iso));

export function formatWait(minutes: number): string {
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  const rest = minutes % 60;
  return rest === 0 ? `${hours} h` : `${hours} h ${rest} min`;
}

export interface PromiseView {
  clock: string;
  relative: string;
  late: boolean;
}

// "Late" is measured against the API's generated_at, never the browser clock,
// so every row in one response agrees on what "now" is.
export function describePromise(promisedAt: string | null, generatedAt: string): PromiseView | null {
  if (promisedAt == null) return null;
  const diffMs = new Date(promisedAt).getTime() - new Date(generatedAt).getTime();
  const minutes = Math.floor(Math.abs(diffMs) / 60000);
  if (diffMs < 0) {
    return { clock: formatClock(promisedAt), relative: minutes < 1 ? 'late' : `${formatWait(minutes)} late`, late: true };
  }
  return { clock: formatClock(promisedAt), relative: minutes < 1 ? 'due now' : `in ${formatWait(minutes)}`, late: false };
}
