import { useCallback, useEffect, useRef, useState } from 'react';
import { ApiError, fetchQueue } from '../api/client';
import type { QueueFilter, QueueResponse } from '../api/types';

export const REFRESH_MS = 20_000;

export interface QueueSnapshot extends QueueResponse {
  filter: QueueFilter;
}

const toApiError = (err: unknown) =>
  err instanceof ApiError ? err : new ApiError({ code: 'CLIENT_ERROR', message: String(err) }, null);

export function useQueue(filter: QueueFilter) {
  const [snapshot, setSnapshot] = useState<QueueSnapshot | null>(null);
  const [loadError, setLoadError] = useState<ApiError | null>(null);
  const [fetching, setFetching] = useState(false);
  const latestRequest = useRef(0);
  const controller = useRef<AbortController | null>(null);

  const refetch = useCallback(async () => {
    // Only the newest request may write state, so a slow response can't overwrite a newer one.
    const requestId = ++latestRequest.current;
    controller.current?.abort();
    const abort = new AbortController();
    controller.current = abort;
    setFetching(true);
    try {
      const response = await fetchQueue(filter, abort.signal);
      if (requestId !== latestRequest.current) return;
      setSnapshot({ ...response, filter });
      setLoadError(null);
    } catch (err) {
      if (abort.signal.aborted || requestId !== latestRequest.current) return;
      setLoadError(toApiError(err));
    } finally {
      if (requestId === latestRequest.current) setFetching(false);
    }
  }, [filter]);

  useEffect(() => {
    refetch();
    const timer = window.setInterval(refetch, REFRESH_MS);
    return () => {
      window.clearInterval(timer);
      controller.current?.abort();
    };
  }, [refetch]);

  return { snapshot, loadError, fetching, refetch };
}
EOF
