import { useEffect, useRef, useState } from 'react';

// Tweens a displayed integer toward `value`: from 0 on mount, then from wherever it is.
export function useCountUp(value: number, animate: boolean, durationMs = 700): number {
  const [display, setDisplay] = useState(animate ? 0 : value);
  const current = useRef(animate ? 0 : value);

  useEffect(() => {
    if (!animate) {
      current.current = value;
      setDisplay(value);
      return;
    }
    const from = current.current;
    if (from === value) return;
    const start = performance.now();
    let frame = 0;
    const tick = (now: number) => {
      const progress = Math.min(1, (now - start) / durationMs);
      const eased = 1 - (1 - progress) ** 3;
      const next = Math.round(from + (value - from) * eased);
      current.current = next;
      setDisplay(next);
      if (progress < 1) frame = requestAnimationFrame(tick);
    };
    frame = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(frame);
  }, [value, animate, durationMs]);

  return display;
}
EOF
cat > motion/useFlip.ts <<'EOF'
import { useLayoutEffect, useRef, type RefObject } from 'react';

// FLIP for list reorders. Children carrying data-flip-key are measured with offsetTop
// (layout position, unaffected by running transforms) after every render; anything that
// moved is inverted to its old spot and animated back to zero.
export function useFlip(container: RefObject<HTMLElement | null>, viewKey: string, enabled: boolean) {
  const positions = useRef(new Map<string, number>());
  const lastView = useRef(viewKey);

  useLayoutEffect(() => {
    const root = container.current;
    if (!root) return;
    const viewChanged = lastView.current !== viewKey;
    lastView.current = viewKey;

    const next = new Map<string, number>();
    root.querySelectorAll<HTMLElement>('[data-flip-key]').forEach((el) => {
      const key = el.dataset.flipKey!;
      const top = el.offsetTop;
      next.set(key, top);
      const previous = positions.current.get(key);
      if (!enabled || viewChanged || previous === undefined) return;
      const delta = previous - top;
      if (Math.abs(delta) < 1) return;
      el.animate([{ transform: `translateY(${delta}px)` }, { transform: 'translateY(0)' }], {
        duration: 450,
        easing: 'cubic-bezier(0.2, 0.8, 0.2, 1)',
      });
    });
    positions.current = next;
  });
}
EOF
