import type { QueueOrder } from '../api/types';
import type { QueueSnapshot } from './useQueue';

export type ExitKind = 'pass' | 'fade';

export interface DisplayRow {
  order: QueueOrder;
  exiting: ExitKind | null;
}

interface Ghost {
  order: QueueOrder;
  index: number;
  kind: ExitKind;
