  pending: boolean;
  animate: boolean;
  onAction: (order: QueueOrder, action: OrderAction) => void;
  onExited: (orderId: number) => void;
}

export function QueueRow({ order, topScore, generatedAt, nextUp, exiting, pending, animate, onAction, onExited }: QueueRowProps) {
  const wrapper = useRef<HTMLDivElement>(null);
  const card = useRef<HTMLDivElement>(null);
  const lastStatus = useRef(order.status);
  const score = useCountUp(order.score, animate);
  const Icon = TYPE_ICON[order.type];

  // Brief highlight when the API reports a new status for this order.
  useEffect(() => {
    if (lastStatus.current === order.status) return;
    lastStatus.current = order.status;
    if (!animate || !card.current) return;
    card.current.animate(
      [
        { boxShadow: `0 0 0 1px ${tokens.lamp}, 0 0 22px rgba(255, 177, 59, 0.45)` },
        { boxShadow: '0 0 0 1px transparent, 0 0 0 rgba(255, 177, 59, 0)' },
      ],
      { duration: 1200, easing: 'ease-out' },
    );
  }, [order.status, animate]);

  // Leaving: let the ball reach the pass (or fade, for a cancel), then collapse the row.
  useEffect(() => {
    if (!exiting) return;
    const el = wrapper.current;
    if (!el || !animate) {
      onExited(order.id);
      return;
    }
    let collapse: Animation | null = null;
    const timer = window.setTimeout(() => {
      collapse = el.animate(
        [
          { height: `${el.offsetHeight}px`, opacity: 1 },
          { height: '0px', opacity: 0 },
        ],
        { duration: 320, easing: 'cubic-bezier(0.4, 0, 0.2, 1)', fill: 'forwards' },
      );
      collapse.onfinish = () => onExited(order.id);
    }, exiting === 'pass' ? BALL_TRAVEL_MS : 380);
    return () => {
      window.clearTimeout(timer);
      collapse?.cancel();
    };
  }, [exiting, animate, onExited, order.id]);

  return (
    <Box
      ref={wrapper}
      data-flip-key={order.id}
      role="listitem"
      aria-hidden={exiting ? true : undefined}
      sx={{ overflow: 'hidden', pb: 0.75, pointerEvents: exiting ? 'none' : undefined }}
    >
      <Box
        sx={{
          display: 'grid',
          gridTemplateColumns: ROW_COLUMNS,
          columnGap: 1.5,
          rowGap: 1,
          alignItems: 'stretch',
          p: 0.75,
          borderRadius: 2,
          border: '1px solid',
          borderColor: nextUp ? tokens.red : 'transparent',
          boxShadow: nextUp ? `0 0 0 1px ${tokens.red}, 0 0 24px rgba(255, 77, 61, 0.28)` : 'none',
          transition: animate ? 'border-color 300ms, box-shadow 300ms' : 'none',
        }}
      >
        <Box
          role="img"
          aria-label={TYPE_LABEL[order.type]}
          title={TYPE_LABEL[order.type]}
          sx={{
            width: { xs: 40, md: 44 },
            height: { xs: 40, md: 44 },
            alignSelf: 'center',
            display: 'grid',
            placeItems: 'center',
            borderRadius: 1.5,
            border: `1px solid ${tokens.rule}`,
            backgroundColor: tokens.card,
            color: tokens.lamp,
          }}
        >
          <Icon fontSize="small" />
        </Box>

        <Box
          ref={card}
          sx={{
            display: 'grid',
            gridTemplateColumns: 'minmax(0, 1fr) auto',
            columnGap: 1.5,
            alignItems: 'center',
            px: 1.5,
            py: 1,
            borderRadius: 1.5,
            backgroundColor: tokens.card,
            border: `1px solid ${tokens.rule}`,
          }}
        >
          <Box sx={{ minWidth: 0 }}>
            <Box sx={{ display: 'flex', alignItems: 'center', gap: 0.75, flexWrap: 'wrap' }}>
              <Box component="span" sx={{ fontWeight: 700, fontSize: 14, color: tokens.text }}>
                {order.customer_name}
              </Box>
              {order.is_vip && (
                <Box
                  component="span"
                  sx={{
                    px: 0.75,
                    fontSize: 10.5,
                    fontWeight: 700,
                    lineHeight: '18px',
                    borderRadius: 1,
                    color: tokens.ink,
                    backgroundColor: tokens.lamp,
                  }}
                >
                  VIP
                </Box>
              )}
              <Box
                component="span"
                sx={{
                  px: 0.75,
                  fontSize: 10.5,
                  lineHeight: '16px',
                  borderRadius: 1,
                  border: `1px solid ${order.status === 'preparing' ? 'rgba(255, 177, 59, 0.5)' : tokens.rule}`,
                  color: order.status === 'preparing' ? tokens.lamp : tokens.muted,
                }}
              >
                {STATUS_LABEL[order.status]}
              </Box>
            </Box>
            <Box
              title={order.items_summary}
              sx={{
                mt: 0.5,
                fontSize: 12,
                color: tokens.muted,
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
              }}
            >
              {TYPE_LABEL[order.type]}: {order.items_summary}
            </Box>
          </Box>
          <Box sx={{ textAlign: 'right', whiteSpace: 'nowrap' }}>
            <Box component="span" aria-hidden sx={{ fontSize: 20, fontWeight: 700, fontStretch: '100%', color: tokens.text }}>
              {score}
            </Box>
            <Box component="span" aria-hidden sx={{ ml: 0.5, fontSize: 11, color: tokens.muted }}>
              pts
            </Box>
            <Box component="span" sx={visuallyHidden}>
              {order.score} points
            </Box>
          </Box>
        </Box>

        <Box sx={{ gridColumn: { xs: '1 / -1', md: 'auto' }, position: 'relative', borderRight: `2px solid ${tokens.lamp}` }}>
          <Lane
            score={order.score}
            topScore={topScore}
            promisedAt={order.promised_at}
            generatedAt={generatedAt}
            exiting={exiting}
            animate={animate}
          />
        </Box>

        <Box
          sx={{
            gridColumn: { xs: '1 / -1', md: 'auto' },
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'space-between',
            gap: 1.5,
          }}
        >
          <Box sx={{ whiteSpace: 'nowrap' }}>
            <Box sx={{ fontSize: 14, fontWeight: 600, color: tokens.text }}>{formatWait(order.minutes_waiting)}</Box>
            <Box sx={{ fontSize: 11, color: tokens.muted }}>waiting</Box>
          </Box>
          <ActionButtons
            actions={order.available_actions}
            customer={order.customer_name}
            disabled={pending || exiting !== null}
            onAction={(action) => onAction(order, action)}
          />
        </Box>
      </Box>
    </Box>
  );
}

const visuallyHidden = {
  position: 'absolute',
  width: 1,
  height: 1,
  overflow: 'hidden',
  clip: 'rect(0 0 0 0)',
  whiteSpace: 'nowrap',
} as const;
