import Box from '@mui/material/Box';
import Button from '@mui/material/Button';
import Skeleton from '@mui/material/Skeleton';
import ToggleButton from '@mui/material/ToggleButton';
import ToggleButtonGroup from '@mui/material/ToggleButtonGroup';
import { ApiError, postAction } from '../api/client';
import type { OrderAction, QueueFilter, QueueOrder } from '../api/types';
import { useQueue } from '../hooks/useQueue';
import { useDisplayRows } from '../hooks/useDisplayRows';
import { useReducedMotion } from '../hooks/useReducedMotion';
import { useFlip } from '../motion/useFlip';
import { ACTION_LABEL, formatClockSeconds } from '../format';
import { tokens } from '../theme';
import { QueueRow, ROW_COLUMNS } from './QueueRow';
import { ErrorBanner } from './ErrorBanner';
import { EmptyState } from './EmptyState';

const FILTERS: { value: QueueFilter; label: string }[] = [
  { value: 'active', label: 'All active' },
  { value: 'received', label: 'Received' },
  { value: 'preparing', label: 'Preparing' },
];

interface ActionFailure {
  error: ApiError;
  context: string;
}

export function KitchenDisplay() {
  const [filter, setFilter] = useState<QueueFilter>('active');
  const [actionFailure, setActionFailure] = useState<ActionFailure | null>(null);
  const [pending, setPending] = useState<ReadonlySet<number>>(new Set());
  const reducedMotion = useReducedMotion();
  const animate = !reducedMotion;

  const { snapshot, loadError, fetching, refetch } = useQueue(filter);
  const { rows, hintExit, finishExit } = useDisplayRows(snapshot, animate);
  const list = useRef<HTMLDivElement>(null);
  useFlip(list, snapshot?.filter ?? filter, animate);

  const handleAction = useCallback(
    async (order: QueueOrder, action: OrderAction) => {
      setPending((current) => new Set(current).add(order.id));
      try {
        const updated = await postAction(order.id, action);
        hintExit(order.id, updated.status === 'cancelled' ? 'fade' : 'pass');
        setActionFailure(null);
      } catch (err) {
        const error = err instanceof ApiError ? err : new ApiError({ code: 'CLIENT_ERROR', message: String(err) }, null);
        setActionFailure({ error, context: `${ACTION_LABEL[action]} for ${order.customer_name} (#${order.id})` });
      } finally {
        setPending((current) => {
          const next = new Set(current);
          next.delete(order.id);
          return next;
        });
        await refetch();
      }
    },
    [hintExit, refetch],
  );

  // Presentation scale only: the ball sits at score / top score. Ranking itself is the API's order.
  const liveOrders = snapshot?.orders ?? [];
  const topScore = liveOrders.reduce((max, o) => Math.max(max, o.score), 0);
  const nextUpId = liveOrders[0]?.id;
  const showingStaleView = snapshot !== null && snapshot.filter !== filter;

  return (
    <Box sx={{ minHeight: '100vh', px: { xs: 1.5, md: 4 }, py: { xs: 2, md: 4 } }}>
      <Box
        component="main"
        sx={{
          maxWidth: 1240,
          mx: 'auto',
          border: `1px solid ${tokens.rule}`,
          borderRadius: 3,
          backgroundColor: tokens.panel,
        }}
      >
        <Box
          component="header"
          sx={{
            display: 'flex',
            flexWrap: 'wrap',
            alignItems: 'flex-end',
            justifyContent: 'space-between',
            gap: 2,
            px: { xs: 2, md: 3 },
            pt: { xs: 2.5, md: 3 },
            pb: 2,
            borderBottom: `1px solid ${tokens.rule}`,
          }}
        >
          <Box>
            <Box
              component="h1"
              sx={{ m: 0, fontSize: { xs: 22, md: 28 }, lineHeight: 1.15, fontWeight: 700, fontStretch: '112.5%', letterSpacing: '-0.01em' }}
            >
              Next up for{' '}
              <Box component="span" sx={{ color: tokens.lamp, textShadow: '0 0 18px rgba(255, 177, 59, 0.35)' }}>
                the pass
              </Box>
            </Box>
            <Box sx={{ mt: 1, fontSize: 12, color: tokens.muted, display: 'flex', alignItems: 'center', gap: 1 }}>
              <Box
                component="span"
                aria-hidden
                sx={{
                  width: 6,
                  height: 6,
                  borderRadius: '50%',
                  backgroundColor: fetching ? tokens.lamp : tokens.rule,
                  transition: 'background-color 200ms',
                }}
              />
              <span aria-live="polite">
                {snapshot
                  ? `${liveOrders.length} ${liveOrders.length === 1 ? 'order' : 'orders'}, ranked at ${formatClockSeconds(snapshot.generated_at)}`
                  : 'Loading the queue'}
              </span>
            </Box>
          </Box>

          <ToggleButtonGroup
            exclusive
            size="small"
            value={filter}
            onChange={(_, value: QueueFilter | null) => value && setFilter(value)}
            aria-label="Filter orders by status"
          >
            {FILTERS.map(({ value, label }) => (
              <ToggleButton key={value} value={value} sx={{ px: 1.75, py: 0.5, fontSize: 12 }}>
                {label}
              </ToggleButton>
            ))}
          </ToggleButtonGroup>
        </Box>

        <Box sx={{ px: { xs: 1.25, md: 2.25 }, pt: 1.5, pb: 2 }}>
          {actionFailure && (
            <Box sx={{ mb: 1.5 }}>
              <ErrorBanner error={actionFailure.error} context={actionFailure.context} onClose={() => setActionFailure(null)} />
            </Box>
          )}
          {loadError && snapshot && (
            <Box sx={{ mb: 1.5 }}>
              <ErrorBanner
                error={loadError}
                severity="warning"
                context={`Showing the queue from ${formatClockSeconds(snapshot.generated_at)}`}
              />
            </Box>
          )}

          {snapshot === null && loadError ? (
            <Box sx={{ py: 4 }}>
              <ErrorBanner error={loadError} context="The queue could not be loaded" />
              <Button variant="outlined" sx={{ mt: 2 }} onClick={() => refetch()}>
                Try again
              </Button>
            </Box>
          ) : snapshot === null ? (
            <Box sx={{ display: 'grid', gap: 1 }}>
              {[0, 1, 2, 3].map((i) => (
                <Skeleton key={i} variant="rounded" height={64} sx={{ bgcolor: tokens.card }} />
              ))}
            </Box>
          ) : (
            <>
              <Box
                aria-hidden
                sx={{
                  display: { xs: 'none', md: 'grid' },
                  gridTemplateColumns: ROW_COLUMNS,
                  columnGap: 1.5,
                  px: 0.75,
                  pb: 0.75,
                  fontSize: 11,
                  color: tokens.muted,
                }}
              >
                <span />
                <span>Order</span>
                <Box sx={{ textAlign: 'right', pr: 1.25, color: tokens.lamp, borderRight: `2px solid ${tokens.lamp}` }}>
                  the pass
                </Box>
                <span />
              </Box>

              {rows.length === 0 && !showingStaleView ? (
                <EmptyState filter={snapshot.filter} onShowAll={() => setFilter('active')} />
              ) : (
                <Box
                  ref={list}
                  role="list"
                  aria-label="Orders ranked by priority"
                  aria-busy={showingStaleView || undefined}
                  sx={{ position: 'relative', opacity: showingStaleView ? 0.45 : 1, transition: 'opacity 150ms' }}
                >
                  {rows.map(({ order, exiting }) => (
                    <QueueRow
                      key={order.id}
                      order={order}
                      topScore={topScore}
                      generatedAt={snapshot.generated_at}
                      nextUp={!exiting && order.id === nextUpId}
                      exiting={exiting}
                      pending={pending.has(order.id)}
                      animate={animate}
                      onAction={handleAction}
                      onExited={finishExit}
                    />
                  ))}
                </Box>
              )}
            </>
          )}
        </Box>
      </Box>
    </Box>
  );
}
