const { chromium } = require('/Users/gustavomatos/Projects/kitchen-challenge/node_modules/@playwright/test');
const OUT = process.argv[2];
const URL = 'http://localhost:5173/';
const tag = process.argv[3] || 'v1';

(async () => {
  const browser = await chromium.launch();
  const shot = (page, name) => page.screenshot({ path: `${OUT}/${tag}-${name}.png`, fullPage: true });

  // Desktop, mid fly-in then settled
  let ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, deviceScaleFactor: 1 });
  let page = await ctx.newPage();
  await page.goto(URL);
  await page.waitForSelector('[role="listitem"]');
  await page.waitForTimeout(250);
  await shot(page, 'desktop-flyin');
  await page.waitForTimeout(1500);
  await shot(page, 'desktop');

  // Cancel confirmation (first received order with a Cancel button)
  await page.getByRole('button', { name: /^Cancel .*order$/ }).first().click();
  await page.waitForTimeout(100);
  await shot(page, 'cancel-confirm');
  await page.keyboard.press('Escape');

  // API error: change an order behind the UI's back, then click its stale action
  const queue = await (await fetch('http://localhost:4000/orders/queue?status=received')).json();
  const target = queue.orders[queue.orders.length - 1];
  await fetch(`http://localhost:4000/orders/${target.id}/start`, { method: 'POST' });
  await page.getByRole('button', { name: `Start: ${target.customer_name}` }).click();
  await page.waitForSelector('[role="alert"]');
  await page.waitForTimeout(1200);
  await shot(page, 'error');
  await ctx.close();

  // Empty state via request interception (no app change)
  ctx = await browser.newContext({ viewport: { width: 1440, height: 700 } });
  page = await ctx.newPage();
  await page.route('**/api/orders/queue?status=preparing', (route) =>
    route.fulfill({ json: { generated_at: new Date().toISOString(), orders: [] } }),
  );
  await page.goto(URL);
  await page.waitForSelector('[role="listitem"]');
  await page.getByRole('button', { name: 'Preparing' }).click();
  await page.waitForTimeout(600);
  await shot(page, 'empty-preparing');
  await ctx.close();

  // Mobile
  ctx = await browser.newContext({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 2 });
  page = await ctx.newPage();
  await page.goto(URL);
  await page.waitForSelector('[role="listitem"]');
  await page.waitForTimeout(1500);
  await shot(page, 'mobile');
  await ctx.close();

  // Reduced motion: should be fully settled immediately
  ctx = await browser.newContext({ viewport: { width: 1440, height: 900 }, reducedMotion: 'reduce' });
  page = await ctx.newPage();
  await page.goto(URL);
  await page.waitForSelector('[role="listitem"]');
  await page.waitForTimeout(150);
  await shot(page, 'reduced-motion');
  await ctx.close();

  await browser.close();
})().catch((e) => { console.error(e); process.exit(1); });
EOF
